"""Figure for notes 21.90-21.91: the within-hour sawtooth of quarter-hour prices; and whether the forecasts already have it."""
import numpy as np, pandas as pd, matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt, warnings; warnings.filterwarnings("ignore")
SP = "/tmp/claude-0/-home-user-EpexPredictor/d6125cc0-c431-5b93-a06f-0110cd871ab6/scratchpad"; BLUE, ORANGE, AQUA, YEL, INK, MUTED, SURF, GRID, NEUT = "#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#0b0b0b", "#52514e", "#fcfcfb", "#e9e8e3", "#a8a79f"
plt.rcParams.update({"font.size": 9, "axes.edgecolor": "#c9c8c2", "axes.labelcolor": MUTED, "xtick.color": MUTED, "ytick.color": MUTED, "figure.facecolor": SURF, "axes.facecolor": SURF, "savefig.facecolor": SURF, "font.family": "DejaVu Sans"})
def clean(a):
    a.grid(True, color=GRID, linewidth=0.6); a.set_axisbelow(True); [a.spines[s].set_visible(False) for s in ("top", "right")]
def ttl(a, t): a.set_title(t, loc="left", fontsize=9.5, fontweight="bold", color=INK)
S = pd.read_parquet(f"{SP}/out/divot_rows.parquet"); fit = S[S.index < "2025-12-01"]; beta = float(np.polyfit(fit.dD, fit.dp, 1)[0]); print("within-hour slope fitted on Oct-Nov 2025 only, ct per GW:", round(beta, 3), "| on the later data:", round(float(np.polyfit(S.dD[S.index >= '2025-12-01'], S.dp[S.index >= '2025-12-01'], 1)[0]), 3))
# do the forecasts already carry the sawtooth?
Z = np.load(f"{SP}/out/day_look.npz"); G = {"winter": "gen_mid_winter", "summer": "gen_mid_summer", "autumn": "gen_v2_autumn", "winterf": "gen_mid_winterf", "summerf": "gen_mid_summerf"}; wh = lambda v: v - np.repeat(v.reshape(len(v), 24, 4).mean(2), 4, 1); res = {}
for p in G:
    a, A, P = (Z[f"{p}_{k}"].astype(float) for k in ("a", "A", "P")); g = np.load(f"{SP}/out/{G[p]}.npz"); xf = g["rl_pes"].astype(float)[:, :96]; xt = g["rl_true"].astype(float)[:, :96]; hm = lambda v: np.repeat(v.reshape(len(v), 24, 4).mean(2), 4, 1); As = hm(A) + beta * wh(xf); Ps = hm(P) + beta * wh(xf); Ao = hm(A) + beta * wh(xt)
    res[p] = dict(within_A=np.abs(wh(A) - wh(a)).mean(), within_P=np.abs(wh(P) - wh(a)).mean(), within_rule=np.abs(beta * wh(xf) - wh(a)).mean(), within_rule_pub=np.abs(beta * wh(xt) - wh(a)).mean(), within_zero=np.abs(wh(a)).mean(), mae_A=np.abs(A - a).mean(), mae_As=np.abs(As - a).mean(), mae_P=np.abs(P - a).mean(), mae_Ps=np.abs(Ps - a).mean(), corr_A=np.corrcoef(wh(A).ravel(), wh(a).ravel())[0, 1], corr_P=np.corrcoef(wh(P).ravel(), wh(a).ravel())[0, 1], corr_rule=np.corrcoef(wh(xf).ravel(), wh(a).ravel())[0, 1], sdA=wh(A).std(), sdP=wh(P).std(), sda=wh(a).std())
    r = res[p]; print(f"{p:8s} within-hour part of the price: actual sd {r['sda']:.2f} ct; A sd {r['sdA']:.2f} corr {r['corr_A']:.2f} error {r['within_A']:.3f}; P sd {r['sdP']:.2f} corr {r['corr_P']:.2f} error {r['within_P']:.3f}; rule beta x forecast ramp: corr {r['corr_rule']:.2f} error {r['within_rule']:.3f} (with the published ramp {r['within_rule_pub']:.3f}; no within-hour shape at all {r['within_zero']:.3f}) | whole-day MAE A {r['mae_A']:.3f} -> with the rule {r['mae_As']:.3f}; P {r['mae_P']:.3f} -> {r['mae_Ps']:.3f}")
fig, axs = plt.subplots(1, 3, figsize=(19.5, 5.2), gridspec_kw=dict(wspace=0.22, width_ratios=[1.25, 1.15, 0.9]))
day = "2026-10-14"; d = S.loc[day]; t = np.arange(len(d)) / 4; ax = axs[0]; hmn = np.repeat(d.p.values.reshape(-1, 4).mean(1), 4); ax.step(t, hmn, where="post", color=NEUT, linewidth=1.6, label="hourly mean of the price"); ax.plot(t + 0.125, d.p.values, "-o", color=INK, linewidth=1.3, markersize=2.6, label="quarter-hour day-ahead price"); ax.set_xlim(0, 24); ax.set_xticks([0, 6, 12, 18, 24]); ax.set_xlabel(f"hour, {day}"); ax.set_ylabel("ct/kWh"); ax.legend(frameon=False, loc="upper left", fontsize=8); clean(ax)
ttl(ax, "One day: inside each hour the price runs with the ramp,\nthen snaps back at the hour boundary")
ax = axs[1]; prof = S.groupby(["hod", "q"]).dp.mean().values; profD = S.groupby(["hod", "q"]).dD.mean().values; tt = np.arange(96) / 4 + 0.125
for h in range(24): ax.plot(tt[4 * h:4 * h + 4], prof[4 * h:4 * h + 4], "-o", color=INK, linewidth=1.5, markersize=2.6, label="price minus its hourly mean, ct/kWh" if h == 0 else None); ax.plot(tt[4 * h:4 * h + 4], profD[4 * h:4 * h + 4], "-", color=ORANGE, linewidth=1.5, label="residual load minus its hourly mean, GW" if h == 0 else None)
ax.axhline(0, color=INK, linewidth=0.5); ax.set_xlim(0, 24); ax.set_xticks([0, 6, 12, 18, 24]); ax.set_xlabel("hour of day (mean over Oct 2025 - Nov 2026)"); ax.set_ylabel("deviation from the hourly mean (ct/kWh and GW share one scale)"); ax.legend(frameon=False, loc="lower left", fontsize=8); clean(ax)
ttl(ax, "On average: a sawtooth with a period of one hour that tracks the\nwithin-hour ramp of residual load, largest at 08-10h and 16-18h")
ax = axs[2]; m = np.random.default_rng(0).choice(len(S), 6000, replace=False); ax.plot(S.dD.values[m], S.dp.values[m], "o", color=NEUT, markersize=2, alpha=0.4, markeredgewidth=0); xs = np.array([-4, 4]); b_in = float(np.polyfit(S.dD, S.dp, 1)[0]); ax.plot(xs, b_in * xs, color=INK, linewidth=1.8, label=f"within the hour: {b_in * 10:.1f} EUR/MWh per GW"); ax.plot(xs, 0.429 * xs, color=BLUE, linewidth=1.8, linestyle=(0, (4, 2)), label="between hourly means: 4.3 EUR/MWh per GW"); ax.set_xlim(-4, 4); ax.set_ylim(-6, 6); ax.set_xlabel("residual load minus its hourly mean, GW"); ax.set_ylabel("price minus its hourly mean, ct/kWh"); ax.legend(frameon=False, loc="upper left", fontsize=8); clean(ax)
ttl(ax, "Moving demand within the hour costs twice as much\nper GW as moving it between hours")
fig.suptitle("The divots: quarter-hour prices follow the within-hour ramp on a thin, steep layer of flexible supply, while the hourly level sits on the full curve", x=0.05, ha="left", fontsize=11, fontweight="bold", color=INK, y=1.03); fig.savefig(f"{SP}/out/divots.png", dpi=100, bbox_inches="tight"); print("ok")
